import json,pathlib
p=pathlib.Path(__file__).with_name('additional_rust_pfp_foundations_supplement.json');d=json.loads(p.read_text())
rows=[
('RPF-F056','medium','Deserialized bytecode executes under a stale bundle digest','epics/bytecode/compile.rs',[[176,211]],'Private fields derive Deserialize without digest reconstruction. Changing LoadGlyph glyph1 to99 in serialized bundle preserves original digest in execution receipt. Validate wire via constructor and recompute/bind bundle plus initial envelope at execution.','Unchanged-source native probe reproduced; no external programs.'),
('RPF-F057','medium','Repeating boundary assertion promotes unresolved defect to exact','epics/bytecode/machine.rs',[[100,121],[176,186]],'EmitObstruction followed by two AssertBoundary operations yields exact=true while defect_count remains1. The second check treats an inexact Boundary as non-Defect. Preserve prior inexactness and require actual boundary-map computation before mathematical exactness claims.','Unchanged-source native probe reproduced; symbolic instruction semantics only.'),
('RPF-F058','medium','Fiber continuation overflows instead of refusing','epics/bytecode/machine.rs',[[122,134]],'A supplied Fiber level u64MAX followed by StepFibration panics with overflow checks and wraps to0 without them. Use checked_add and typed refusal.','Both native overflow modes reproduced; hand-constructed public envelope.'),
('RPF-F059','medium','Guard generalization can bypass review and preserve an obsolete mask digest','epics/guard.rs',[[114,181],[255,267]],'Public LearnedGuard/scope fields and Deserialize admit generalized scope without named review. Mask digest omits scope/reviewer/rationale, so changing exact matching into token-only pruning preserves digest. Validate all constructors/wire and hash complete behavior/review evidence.','Source-established, not a newly executed guard probe; bounded known-good panel cannot establish universal soundness.'),
('RPF-F060','medium','CODA wire bypasses layer and named-review gates','epics/coda.rs',[[173,242],[269,336]],'Deserialize admits a Physical AdmittedClaim carrying ParityWitness and a QuarantinedAdapter certificate with empty reviewer/rationale; author_receipt succeeds. Use validated wire conversion and distinguish evidence-tag checks from actual evidence verification.','Both bypasses reproduced against unchanged source. No physical or parity truth inferred.'),
('RPF-F061','medium','Retraction replay ignores material receipt fields','epics/retraction.rs',[[364,378],[461,496]],'Replay compares terminal, trace and cemetery but ignores schema, acts, admitted/refused counts, open-obligation count within same terminal category and authority effect. Tampering those fields remains Reproduced. Compare the complete canonical receipt or explicitly name a narrower replay predicate.','Source-established; authority string acceptance is not demonstrated external authority issuance.'),
('RPF-F062','medium','Debate localization omits its monotonicity and common-proposition premises','epics/debate.rs',[[243,317],[402,426],[534,557]],'Binary search assumes prefix agreement followed by permanent disagreement. Public DAG permits nonmonotone bits; a local previous-node check cannot establish first divergence. Comparisons also ignore primitive identity and intentionally compare different propositions, so differing truth bits need not be contradictory. Encode/check premises or narrow the contract to locating a local bit transition.','Source-established with monotone-only existing fixtures; no fresh debate execution yet.')]
for ident,severity,title,file,ranges,detail,limits in rows:
 row={'id':ident,'severity':severity,'title':title,'evidence':[{'path':'code/rust/pfp/src/'+file,'lines':r}for r in ranges],'status':'bounded native probe reproduced'if ident in ['RPF-F056','RPF-F057','RPF-F058','RPF-F060']else'source-established','detail':detail,'limits':limits}
 if not any(x['id']==ident for x in d['findings']):d['findings'].append(row)
v={'id':'RPF-V022','kind':'Symbolic bytecode and CODA wire probes; existing bytecode tests','details_file':'additional_rust_pfp_foundations_epic_validation.json','limits':'Unchanged complete owners and cached dependencies, both overflow modes;50existing bytecode tests passed. No full crate suite, external candidate, provider, benchmark or private input.'}
if not any(x['id']==v['id']for x in d['validation']):d['validation'].append(v)
p.write_text(json.dumps(d,indent=2)+'\n')
